93	// A major command line at column 0: `name   brief`.
94	void print_major(std::FILE* out, const char* name, const char* brief) {
95	  std::fprintf(out, "%-7s %s\n", name, brief);
96	}
97	
98	// A subcommand/target line, indented two under its command: `  name   brief`.
99	void print_sub(std::FILE* out, const char* name, const char* brief) {
100	  std::fprintf(out, "  %-9s %s\n", name, brief);
101	}
102	
103	// An option line: `<indent>--flag    [TAG  ]brief`, flags aligned to a column.
104	void print_opt(std::FILE* out, const OptRow& o) {
105	  if (o.tag[0])
106	    std::fprintf(out, "%-29s %s  %s\n", o.flag, o.tag, o.brief);
107	  else
108	    std::fprintf(out, "%-29s %s\n", o.flag, o.brief);
109	}
110	
111	// `run`: major line, the mode subcommands, then the option list (dev options
112	// only under ANDESIM_DEV). Shared by the top-level tree and `run --help`.
113	void print_run_block(std::FILE* out) {
114	  print_major(out, "run", "run one simulation (the default: 'run' may be omitted)");
115	  for (const ModeRow& m : kRunModes) print_sub(out, m.name, m.brief);
116	  std::fputs("\n", out);
117	  for (const OptRow& o : kRunOpts) {
118	    if (o.dev && !is_dev_mode()) continue;
119	    print_opt(out, o);
120	  }
121	}
122	
123	void print_list_block(std::FILE* out) {
124	  print_major(out, "list", "list what is available");
125	  for (const TargetRow& t : kListTargets) {
126	    if (t.dev && !is_dev_mode()) continue;
127	    print_sub(out, t.name, t.brief);
128	  }
129	}
130	
131	// ... and `profile`'s options (the report knobs; the QEMU shape -- binary,
132	// -cpu, -readconfig -- comes from the engine, not from flags).
133	constexpr OptRow kProfileOpts[] = {
134	    {"  --engine <id>", "", "the engine whose QEMU config to profile on (default: the sole one)", false},
135	    {"  --limit <N>", "", "report the top-N loops (default 50)", false},
136	    {"  --min-iters <N>", "", "drop loops with fewer iterations (default 1)", false},
137	    {"  --no-optimize-rvv", "", "keep scalar loops too (default: RVV-only)", false},
138	    {"  --no-llm", "", "plain table instead of the LLM Markdown report", false},
139	    {"  --no-source", "", "skip source file:line resolution (addr2line)", false},
140	    {"  --objdump <bin>", "", "override the disassembler (default: $HYBRID_TOOLCHAIN's)", false},
141	    {"  --addr2line <bin>", "", "override the source resolver", false},
142	    {"  --raw", "", "dump the raw plugin log, no report", false},
143	    {"  --mem-size <spec>", "", "guest RAM, forwarded as QEMU -m", false},
144	    {"  --dry-run", "", "print the exact QEMU command and exit, running nothing", false},
145	    {"  -- <args...>", "", "forward everything after -- verbatim to QEMU", false},
146	};
147	
148	void print_profile_block(std::FILE* out) {
149	  print_major(out, "profile",
150	              "find hot loops under QEMU, configured like the engine "
151	              "(reports --pc-start/--pc-end windows for hybrid)");
152	  std::fputs("\n", out);
153	  for (const OptRow& o : kProfileOpts) print_opt(out, o);
154	}
155	
156	void print_doctor_block(std::FILE* out) {
157	  print_major(out, "doctor", "check toolchain + fixtures are present");
158	}
159	
160	// Top-level `andesim --help`: the whole tree -- every major command, its
161	// subcommands, and run's full option list, so one screen shows everything.
162	void print_usage(std::FILE* out) {
163	  std::fputs("usage: andesim [command] [options] <ELF> [-- <engine args>]\n\n",
164	             out);
165	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
166	             out);
167	  print_run_block(out);
168	  std::fputs("\n", out);
169	  print_profile_block(out);
170	  std::fputs("\n", out);
171	  print_list_block(out);
172	  std::fputs("\n", out);
173	  print_doctor_block(out);
174	  std::fputs(
175	      "\n'andesim run --help' / 'andesim profile --help' / 'andesim list "
176	      "--help' for per-command detail.\n",
177	      out);
178	}
179	
180	// Per-command `andesim <cmd> --help`: the matching slice of the same tree.
181	// parse_cli admits only run/list/doctor/profile, so `run` is the fallthrough.
182	void print_subcommand_help(std::string_view name, std::FILE* out) {
183	  if (name == "list") { print_list_block(out); return; }
184	  if (name == "doctor") { print_doctor_block(out); return; }
185	  if (name == "profile") { print_profile_block(out); return; }
186	  print_run_block(out);
187	}
